import itertools
import json

def solve_puzzle():
    # Define houses and attributes
    houses = [1, 2]  # left to right
    attributes = {
        "name": ["Arnold", "Eric"],
        "birthday month": ["april", "sept"],
        "mothers' names": ["Aniya", "Holly"],
    }

    # Helper to check left-of relation using positions in assigned lists
    def is_left_of(pos_a, pos_b):
        return pos_a < pos_b

    solutions = []

    # Iterate over all permutations for each attribute category
    for names in itertools.permutations(attributes["name"]):
        for months in itertools.permutations(attributes["birthday month"]):
            # Clue 2: The person whose birthday is in April is in the first house.
            if months[0] != "april":
                continue

            for mothers in itertools.permutations(attributes["mothers' names"]):
                # Clue 1: Eric is somewhere to the left of the person whose mother's name is Holly.
                pos_eric = names.index("Eric")
                pos_holly_mom = mothers.index("Holly")
                if not is_left_of(pos_eric, pos_holly_mom):
                    continue

                # If all constraints satisfied, record solution
                solutions.append({
                    "names": names,
                    "months": months,
                    "mothers": mothers
                })

    # Expect a unique solution
    if not solutions:
        raise ValueError("No solution found.")
    if len(solutions) > 1:
        # Still output the first solution, but this indicates non-uniqueness
        solution = solutions[0]
    else:
        solution = solutions[0]

    # Build output
    header = ["House", "name", "birthday month", "mothers' names"]
    rows = []
    for i, house in enumerate(houses):
        rows.append([
            str(house),
            solution["names"][i],
            solution["months"][i],
            solution["mothers"][i],
        ])

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
